"""Get close to <target> by doing a numeric derivative"""
def _numeric_derivative(
    y0: Any, y1: Any, err: Any, target: Any, x_min: Any, x_max: Any, x0: Any, x1: Any
) -> object {
    if (abs((y1 - y0)) < err) {
        return (0.0, x1, x1);
    }
    x = (((target - y0) / (y1 - y0)) * (x1 - x0)) + x0;
    x = min(x, x_max);
    x = max(x, x_min);
    dx = abs((x - x1));
    x0 = x1;
    x1 = x;
    return (dx, x0, x1);
}

"""creates a binary list, indicating inputlist entries are
between (inclusive) the minval and maxval"""
def getinrangelist(inputlist: Any, minval: Any, maxval: Any) -> object {
    inrangelist = [1 if (maxval >= i >= minval) else 0 for i in inputlist];
    return inrangelist;
}
